import Foundation

/// What a canvas gesture edits (spec §11 CI-13): the clip's BASE props, or
/// the selected action's END state — the same choice the inspector's fields
/// make (CI-2), so a drag, a nudge and a typed value all write one place.
///
/// It reaches the canvas as a value on two channels: the refresh that already
/// follows a selection (`EditorViewController.refreshCanvas`) and the
/// playhead's own path (`canvasPlayheadMoved`, since the entry rule selects
/// an action without a refresh). A gesture captures it at mouse-down as
/// `PreviewCanvasView.gestureTarget` and writes through that for every tick,
/// and the sessions in `CanvasSessions.swift` ask it for their ops rather
/// than naming `set_video` themselves. A multi-selection is always `.base`:
/// no action is selected then (CI-1).
///
/// **The box on screen is still the frame at the PLAYHEAD.** A gesture
/// STARTS from `start(of:in:)` — the end state, for the selected action's
/// clip — and moves it by the pointer's travel: the inspector's "fields show
/// the value they write", carried to the handles.
struct CanvasEditTarget: Equatable {
    struct Selected: Equatable {
        let clip: UInt32
        let action: UInt32
        /// The action's end in CLIP time (`ActionSnapshot.endTime`).
        let endTime: Ticks
    }

    /// What a gesture starts from: the end state for `selected.clip`, the
    /// base for any other clip. `text` is carried because a text clip's
    /// wrap-width drag reads it (`PreviewCanvasView.beginScale`).
    struct Start {
        let video: VideoProps
        let text: TextProps?
    }

    /// nil: base props.
    let selected: Selected?

    static let base = CanvasEditTarget(selected: nil)

    /// The document's mode: the selected action of `singleSelectedClip`,
    /// else `.base`.
    static func current(_ document: ProjectDocument) -> CanvasEditTarget {
        guard let clip = document.singleSelectedClip,
              let action = document.selectedActionSnapshot
        else { return .base }
        return CanvasEditTarget(
            selected: Selected(clip: clip.id, action: action.id, endTime: action.endTime))
    }

    /// The action this target writes on `clip`, nil when `clip` is written
    /// at its base.
    private func action(on clip: UInt32) -> UInt32? {
        guard let selected, selected.clip == clip else { return nil }
        return selected.action
    }

    /// `set_action_end` for the selected action's clip, `set_video` for any
    /// other. The typed builder lifts a `.some(nil)` into `off` (CI-14).
    func op(video patch: VideoPatch, clip: UInt32) -> ReelOp {
        guard let action = action(on: clip) else { return .setVideo(clips: [clip], patch: patch) }
        return .setActionEnd(clip: clip, action: action, patch: ActionPatch(video: patch))
    }

    /// The same rule for a text clip's wrap width.
    func op(text patch: TextPatch, clip: UInt32) -> ReelOp {
        guard let action = action(on: clip) else { return .setText(clips: [clip], patch: patch) }
        return .setActionEnd(clip: clip, action: action, patch: ActionPatch(text: patch))
    }

    /// `clip_state` at `clip.start + endTime` decoded through
    /// `InspectorBinding.decode` — the inspector's own read of an END state,
    /// video and text from ONE call — for `selected.clip`; the clip's base
    /// props otherwise. A group the core does not answer falls back to base.
    func start(of clip: ClipSnapshot, in project: ReelProject?) -> Start {
        guard let selected, selected.clip == clip.id,
              let raw = project?.clipState(clip.id, at: clip.start + selected.endTime)
        else { return Start(video: clip.videoProps, text: clip.text) }
        return Start(
            video: InspectorBinding.decode(VideoProps.self, raw["video"]) ?? clip.videoProps,
            text: InspectorBinding.decode(TextProps.self, raw["text"]) ?? clip.text)
    }

    /// The target a SCALE on `clip` starts from and writes: `.base` for a
    /// shape, whose scale is its box — `set_shape` has no action form, and
    /// the `set_video` that pins the pivot must land beside it on the same
    /// state (CI-13) — and `self` for anything else.
    func forScale(of clip: ClipSnapshot) -> CanvasEditTarget {
        if case .shape = clip.source { return .base }
        return self
        if props.textCase != .asWritten || props.wordStyle != nil {
            let style = props.wordStyle
            key += [
                props.textCase.rawValue, style.map { "\($0.activeScale)" } ?? "-",
                style?.activePill.map { "\($0.padding)" } ?? "-", "\(style != nil)",
            ]
        }
        return key.joined(separator: "\u{1}")
    }

    /// CoreText's "no constraint". `CGFloat.greatestFiniteMagnitude` makes
    /// the framesetter's arithmetic overflow into NaN on some fonts; a large
    /// finite number does not.
    private static let unconstrained: CGFloat = 100_000

    private static func measure(_ props: TextProps) -> CGSize {
        let attributed = attributedString(props)
        guard attributed.length > 0 else { return CGSize(width: 1, height: 1) }
        let framesetter = CTFramesetterCreateWithAttributedString(attributed)
        var fitRange = CFRange()
        let constraint = CGSize(
            width: props.width.map { max(1, CGFloat($0)) } ?? unconstrained,
            height: unconstrained)
        let suggested = CTFramesetterSuggestFrameSizeWithConstraints(
            framesetter, CFRange(location: 0, length: 0), nil, constraint, &fitRange)
        let insets = textInsets(props)
        let width = (props.width.map { CGFloat($0) } ?? suggested.width) + insets.x * 2
        let height = suggested.height + insets.y * 2
        return CGSize(
            width: min(CGFloat(maxTextureSide), max(1, width.rounded(.up))),
            height: min(CGFloat(maxTextureSide), max(1, height.rounded(.up))))
    }

    /// The margin around the laid-out text, per axis: the backdrop's
    /// padding, and enough room for the outline, whose stroke straddles the
    /// glyph edge — plus, on a word-styled page, the room its active word's
    /// pop and pill need (`wordHeadroom`, zero for everything else, so an
    /// unstyled text's two insets are the one it always had).
    static func textInsets(_ props: TextProps) -> (x: CGFloat, y: CGFloat) {
        let outline = props.outline.map { CGFloat($0.width) } ?? 0
        let padding = props.backdrop.map { CGFloat($0.padding) } ?? 0
        let base = max(outline, padding)
        let headroom = wordHeadroom(for: props)
        return (x: base + headroom.width, y: base + headroom.height)
    }

    static func attributedString(_ props: TextProps) -> NSAttributedString {
        NSAttributedString(string: props.laidContent, attributes: textAttributes(props))
    }

    /// The one attribute set a text is laid out in: the font, the fill, the
    /// paragraph style, the kern and the outline. `scale` multiplies every
    /// LENGTH — the font size and the kern — so the canvas's text editor
    /// takes the render's own set at view points (spec §11 K-3); the stroke
    /// is a percentage of the font size and so scale-free. At scale 1 every
    /// value is the one the render has always laid out.
    static func textAttributes(
        _ props: TextProps, scale: CGFloat = 1
    ) -> [NSAttributedString.Key: Any] {
        let size = max(1, CGFloat(props.size))
        let font = CTFontCreateWithName(props.font as CFString, size * scale, nil)
        let paragraph = NSMutableParagraphStyle()
        switch props.align {
        case "left": paragraph.alignment = .left
        case "right": paragraph.alignment = .right
        default: paragraph.alignment = .center
        }
        // `lineSpacing` is a MULTIPLE of the natural line height (§5.2), not
        // a point value, which is `lineHeightMultiple`, not `lineSpacing`.
        if props.lineSpacing > 0, props.lineSpacing != 1 {
            paragraph.lineHeightMultiple = CGFloat(props.lineSpacing)
        }
        var attributes: [NSAttributedString.Key: Any] = [
            .font: font,
            .foregroundColor: props.color.nsColor,
            .paragraphStyle: paragraph,
        ]
        if props.tracking != 0 { attributes[.kern] = CGFloat(props.tracking) * scale }
        if let outline = props.outline {
            // A NEGATIVE stroke width means "fill AND stroke", and the value
            // is a PERCENTAGE of the font size — positive would draw the
            // outline only and lose the fill.
            attributes[.strokeWidth] = -CGFloat(outline.width) / size * 100
            attributes[.strokeColor] = outline.color.nsColor
        }
        return attributes
    }

    // MARK: - Laid-out text

    /// One laid-out line, with the geometry a reveal needs and nothing else.
    struct TextLine {
        let line: CTLine
        /// The line's origin in the BITMAP's coordinates (y up), the frame
        /// path's own origin already added.
        let origin: CGPoint
        /// The line's range in the attributed string, in UTF-16 units —
        /// which is the unit every CoreText string index is in.
        let range: CFRange
        let ascent: CGFloat
        let descent: CGFloat

//! What a text layer SHOWS at one instant: [`Reveal`] — the amount, the
//! phase and the kind that `text.animation` resolves to (spec §5.2, §7.3)
//! — the [`text_hash`] that folds all three, and a word-timed page's five
//! word keys, into the layer's cache key, the [`text_source`] that
//! assembles the `source` object a text layer carries, and the one text
//! layer the core writes itself, the timecode
//! [`burn_in_layer`].
//!
//! Split out of `recipe.rs` under the size rule (core/CLAUDE.md: a module
//! at ~600 lines gives something up BEFORE it takes anything on) when road
//! map 2's phase 7 came to it owing a burn-in timecode layer and found it
//! standing at exactly 600. `model.rs` → `model_query.rs`,
//! `model_props.rs` → `model_regions.rs` and `model_props.rs` →
//! `model_text.rs` are the precedent, and so is their rule: cut along a
//! seam somebody can NAME, and re-export the piece taken out so no path
//! anywhere else changes.
//!
//! # The seam: placement, and the one layer that is not finished by it
//!
//! `recipe.rs` asks one question of every layer — where on the canvas, how
//! big, how turned, how combined with what is under it — and asks it
//! identically of a movie, an image, a shape and a text clip. Every answer
//! is a quantity the model already holds and `actions.rs` has already
//! resolved, so the file is a fold over instances and nothing in it needs
//! to know what any layer DEPICTS.
//!
//! Text is the one kind that is not finished when its placement is. The
//! model can only state an intent — these words, that font — because only
//! the platform can lay a string out; `model_text.rs` argues that seam in
//! the schema, and this is the same seam one stage downstream. An ANIMATED
//! layer is not even a fixed intent: what is showing depends on the clip
//! time, so the recipe has to compute a number no property of the clip
//! holds, decide which of two orders the renderer draws in, and then
//! guarantee both reach the texture cache as part of its KEY or a
//! per-frame picture is served a stale texture. A ramp, a plateau, a phase
//! and a hash over all three is the only arithmetic in the recipe that is
//! about a layer's CONTENT rather than its placement, and it is a hundred
//! and eighty lines of it. Taking it out leaves `recipe.rs` the fold it
//! reads as.
//!
//! # What is NOT here
//!
//! [`crate::recipe::content_hash`] and the FNV under it live in
//! `recipe_hash.rs`, re-exported `pub(crate)` by `recipe.rs` for this file
//! to call: a SHAPE layer hashes its description through the same
//! function, so the hash is the recipe's texture-cache primitive and not a
//! text concern. The layer object around `source` stays in `recipe.rs`
//! too, and so does the arm that decides a clip HAS a text description at
//! all — this file is handed one, which is what lets it serve a layer the
//! core synthesizes as readily as one it read off a clip.
//!
//! # Paths
//!
//! `recipe.rs` re-exports [`text_source`] with
//! `pub(crate) use crate::recipe_text::text_source`, so
//! `crate::recipe::text_source` resolves as though the cut had not
//! happened. [`burn_in_layer`] is `pub(crate)` and `recipe.rs` calls it by
//! its own path. [`ramp`] is `pub(crate)` for `recipe_words.rs`, whose
//! every division it is. Nothing else here is reachable from outside the
//! file: [`Reveal`], [`text_hash`] and [`reveal_kind`] were private to
//! `recipe.rs` before the move and are private to this file after it.

