        let rect = CGRect(
            x: insets.x, y: y, width: size.width - insets.x * 2, height: height)
        let frame = CTFramesetterCreateFrame(
            framesetter, CFRange(location: 0, length: 0), CGPath(rect: rect, transform: nil), nil)

