        guard !lines.isEmpty else { return TextLayout(size: size, frame: frame, lines: []) }
        var origins = [CGPoint](repeating: .zero, count: lines.count)
        CTFrameGetLineOrigins(frame, CFRange(location: 0, length: 0), &origins)
