//! The described clips — text, shape, and the shared tail graphic and
//! adjustment clips use — a pure move out of `edit_clip.rs`.
//!
//! The two ops here that DO take a patch — `add_text_clip` and
//! `add_shape_clip` — build their preset and then hand it to `edit_props`'s
//! merge and `props_check`'s checks, so a `text` argument is validated
//! exactly as a later `set_text` would be.

use serde_json::Value;

use crate::edit_clip::DEFAULT_CLIP_DURATION;
use crate::model::{
    Clip, GraphicProps, Project, ShapeKind, ShapeProps, Source, TextProps, VideoProps,
};
use crate::outcome::Outcome;
use crate::patch::{merge_group, Group};
use crate::props_check::{check_shape, check_text};
use crate::time::Ticks;

/// The font of the Title text preset (spec §4.3). A concrete face, not a
/// family: the renderer asks for exactly this name, and a bold weight is
/// what a title over footage needs to stay legible.
const TITLE_FONT: &str = "SourceSans3-Bold";

/// Placeholder content for a new text clip. A text clip that renders
/// nothing is indistinguishable from a broken one, so a new one says what
/// it is and arrives selected for the user to overtype.
const TITLE_CONTENT: &str = "Title";

/// What a sourceless clip — text, shape or graphic — is made of, so the
/// shared placement tail takes one argument instead of five.
pub(crate) struct Described {
    pub(crate) source: Source,
    pub(crate) scale: f64,
    pub(crate) text: Option<TextProps>,
    pub(crate) shape: Option<ShapeProps>,
    pub(crate) graphic: Option<GraphicProps>,
}

impl Project {
    /// A text clip at `at` on `track`: the Title preset, centered, five
    /// seconds by default, with `text` merged over it as a `set_text`
    /// patch (spec §6, §4.3).
    ///
    /// Refuses on an overlap-rule violation, in the rule's own sentence;
    /// `Err` for an unknown track, a non-positive duration, or a bad patch.
    pub fn add_text_clip(
        &self,
        track: u32,
        at: Ticks,
        duration: Option<Ticks>,
        text: Option<&Value>,
    ) -> Result<Outcome, String> {
        let title = TextProps {
            content: TITLE_CONTENT.to_string(),
            font: TITLE_FONT.to_string(),
            size: 72.0,
            color: [1.0, 1.0, 1.0, 1.0],
            ..TextProps::default()
        };
        let props = match text {
            None => title,
            Some(patch) => {
                let mut props = merge_group(&title, patch, Group::Text)?;
                check_text(&props)?;
                // The same door `set_text` is, ticks included
                // (`edit_props.rs`'s `snap_animation`, and the Times rule
                // it keeps).
                self.snap_animation(&mut props);
                props
            }
        };
        self.add_described_clip(
            track,
            at,
            duration,
            Described {
                source: Source::Text,
                // Text has no source size — only the platform can measure a
                // layout — so a new text clip is always at native scale.
                scale: 1.0,
                text: Some(props),
                shape: None,
                graphic: None,
            },
        )
    }

    /// A shape clip at `at` on `track`: the default stroked box, five
    /// seconds by default, with `shape` merged over it as a `set_shape`
    /// patch (spec §6). An arrow is created with its head on.
    pub fn add_shape_clip(
        &self,
        track: u32,
        at: Ticks,
        duration: Option<Ticks>,
        shape: Option<&Value>,
    ) -> Result<Outcome, String> {
        let props = match shape {
            None => ShapeProps::default(),
            Some(patch) => {
                // An arrow with `arrow_end: false` draws as a plain diagonal
                // line, which is not what asking for an arrow means and not
                // what spec §5.2's own arrow example shows. The head is
                // switched on HERE, in the creation preset, rather than in
                // `ShapeProps::default()`: that default is also the base a
                // stored shape is deserialized against and the value a
                // later `set_shape { "kind": "arrow" }` merges into, and a
                // patch that re-paints a field the caller did not name
                // would break the merge contract. Merging the patch over
                // this preset (not under it) keeps an explicit
                // `"arrow_end": false` winning.
                let kind = patch
                    .get("kind")
                    .and_then(|value| serde_json::from_value(value.clone()).ok());
                let base = ShapeProps {
                    arrow_end: matches!(kind, Some(ShapeKind::Arrow)),
                    ..ShapeProps::default()
                };
                let props = merge_group(&base, patch, Group::Shape)?;
                check_shape(&props)?;
                props
            }
        };
        // A shape's box IS its source size, so an oversized one fits like
        // oversized footage does.
        let scale = self.fit_scale(props.width, props.height);
        self.add_described_clip(
            track,
            at,
            duration,
            Described {
                source: Source::Shape,
                scale,
                text: None,
                shape: Some(props),
                graphic: None,
            },
        )
    }

    /// The shared tail of `add_text_clip`, `add_shape_clip` and
    /// `edit_graphic.rs`'s `add_graphic_clip`: a clip with no source bound,
    /// placed under the same rules as any other.
    pub(crate) fn add_described_clip(
        &self,
        track: u32,
        at: Ticks,
        duration: Option<Ticks>,
        described: Described,
    ) -> Result<Outcome, String> {
        self.require_track(track)?;
        let at = self.snapped(at).max(0);
        let duration = match duration {
            None => DEFAULT_CLIP_DURATION,
            Some(given) => {
                let snapped = self.snapped(given);
                if snapped < self.frame() {
                    return Err(format!(
                        "clip duration must be at least one frame ({} ticks), not {given}",
                        self.frame()
                    ));
                }
                snapped
            }
        };

        let mut next = self.clone();
        let clip = Clip {
            video: Some(VideoProps {
                scale: described.scale,
                ..VideoProps::default()
            }),
            text: described.text,
            shape: described.shape,
            graphic: described.graphic,
            ..Clip::placed(next.allocate_id(), track, at, duration, described.source)
        };
        self.commit_additions(next, vec![clip])
    }
}

    if over <= 0 {
        return 1.0;
    }
    let progress = elapsed.max(0) as f64 / over as f64;
    // Both sides are integers, so today this cannot be anything but finite.
    // The guard is one comparison and it fails toward SHOWING the text,
    // where `number()` would turn a non-finite amount into 0.0 and show
    // none of it.
    if progress.is_finite() {
        progress.clamp(0.0, 1.0)
    } else {
        1.0
    }
}

/// The cache key for a text layer: its description, and the reveal when
/// there is one.
///
/// The reveal changes the PIXELS, and this hash is the only thing standing
/// between a per-frame value and a stale texture — Swift caches a rendered
/// paragraph under `"text:" + hash` and consults nothing else — so a frame
/// at one reveal must not be able to collide with the same text at another.
/// A reveal that changed the picture without changing the key would render
/// correctly in a single `render_frame` and freeze during playback, with no
/// error anywhere.
///
/// All THREE computed keys go in, not just the amount: a word fade and a
/// typewriter half done are two different pictures of the same text, and so
/// are a half-arrived and a half-departed line rise.
///
/// A layer with NO animation hashes the bare description, byte for byte as
/// it did before format version 5, so no shipped project's texture cache
/// behaves differently after this phase. An ANIMATED layer keeps its own
/// key even at amount 1: whether a full reveal draws exactly what no
/// animation draws is the renderer's promise, and a cache key must not lean
/// on one.
///
/// `words` is `Some` only when the text has a `word_style` (spec §11, W-4),
/// and then all five word keys go in too: a page is a different picture at
/// every word, and through a glide, a fill and a dim (W-13). Otherwise the
/// hash is exactly what it was before format version 9, `words` or not.
fn text_hash(description: &Value, reveal: &Reveal, words: Option<&Words>) -> String {
    if reveal.phase.is_none() && words.is_none() {
        return content_hash(description);
    }
    let mut keyed = Map::new();
    keyed.insert("text".to_string(), description.clone());
    if let Some(phase) = reveal.phase {
        keyed.insert("reveal".to_string(), number(reveal.amount));
        keyed.insert("reveal_phase".to_string(), Value::from(phase));
        keyed.insert("reveal_kind".to_string(), reveal_kind(reveal));
    }
    if let Some(words) = words {
        words.insert_into(&mut keyed);
    }
    content_hash(&Value::Object(keyed))
}

/// The reveal's kind as the recipe carries it: the schema's own spelling of
/// the variant, or `null` for a layer with no animation.
fn reveal_kind(reveal: &Reveal) -> Value {
    match reveal.kind {
        Some(kind) => json(&kind),
        None => Value::Null,
    }
}

/// A text layer's `source` object (spec §7.3): the description Swift lays
/// out, the hash it caches the laid-out result under, and the eight
/// computed keys that say how much of the description is showing — three
/// for the reveal, five for a word-timed page's words.
///
/// It takes a description, a clip time and a duration and nothing else —
/// no clip, no instance, no `Evaluated` — for [`Reveal`]'s reason read one
/// step further on: a text layer the core SYNTHESIZES has none of those to
/// offer, and this is the one function that would otherwise stop it being
/// a text layer like any other. `recipe.rs`'s `Source::Text` arm is what
/// digs the description out of an evaluated clip; everything after that is
/// here.
pub(crate) fn text_source(text: &TextProps, clip_t: Ticks, duration: Ticks) -> Value {
    // A styled page is a WHOLE reveal: `word_style` and `animation` do not
    // compose, and `word_style` wins (spec §11, W-5).
    let reveal = match text.word_style {
        Some(_) => Reveal::WHOLE,
        None => Reveal::of(text.animation.as_ref(), clip_t, duration),
    };
    let words = Words::of(text, clip_t, duration);
    let mut description = json(text);
    // The animation is STRIPPED from the description carried here: the
    // computed reveal below is the only account of it a renderer gets.
    // Left in, it would be a second one — and the wrong one, since
    // nothing downstream has the clip time to evaluate it against.
    // Removing it also keeps an unanimated clip's hash byte-identical to
    // what it was before format version 5. The inspector reads the
    // animation FIELD through `clip_state`; this description is what
    // draws.
    //
    // Version 9's keys ride in the description only when they change the
    // picture, so an unstyled, as-written title hashes byte for byte as it
    // did before them: `words` never (the computed `word` below is the
    // renderer's only account of them, W-4), `word_style` only when set,
    // `case` only when it is not `as_written`.
    if let Some(map) = description.as_object_mut() {
        map.remove("animation");
        map.remove("words");
        if text.word_style.is_none() {
            map.remove("word_style");
        }
        if text.case == TextCase::AsWritten {
            map.remove("case");
        }
    }
    let styled = text.word_style.is_some().then_some(&words);
    let mut source = Map::new();
    source.insert("kind".to_string(), Value::from("text"));
    source.insert(
        "hash".to_string(),
        Value::from(text_hash(&description, &reveal, styled)),
    );
    source.insert("text".to_string(), description);
    // The three computed reveal keys ride INSIDE the source object, where the
    // kind-specific description already lives, and all three are emitted
    // on every text layer whether it animates or not: an absent key would
    // mean two things — no animation here, or an older core that never
    // computed one — which is the argument `obscure` settled one layer
    // up. A layer-level key instead would put a null on every layer that
    // can never carry one.
    //
    // Together they are the WHOLE of what a renderer is told about the
    // animation: which routine (`reveal_kind`), how far (`reveal`), and
    // which way (`reveal_phase`). The two nulls always travel together —
    /// so a probe can read the pixels a word caption lands (road map 8's
    /// W3) without a texture in the way.
    func renderTextBitmap(_ props: TextProps, reveal: RecipeReveal) -> CGContext? {
        Self.textBitmap(props, reveal: reveal)
    }

    /// `renderTextBitmap`'s body, static so the Generate Captions sheet's
    /// preview (road map 8's W4b) draws with the renderer's own routine and
    /// no Metal device.
    ///
    /// A timed page's pause dim is in this bitmap only when the page has a
    /// backdrop. With none the bitmap is the undimmed page's, byte for byte,
    /// and the compositor's layer opacity carries the dim
    /// (`wordDim(of:reveal:)`, `RecipeLayer.drawnOpacity`, spec §11 W-16).
    /// With one, a TIMED page draws its words first — a dim is then one
    /// multiply of them (`drawWords`) — and its backdrop UNDER them; every
    /// other page draws its backdrop first (spec §11 W-17).
    static func textBitmap(_ props: TextProps, reveal: RecipeReveal) -> CGContext? {
        let layout = LayerRenderers.layout(for: props)
        guard let context = LayerRenderers.bitmap(layout.size) else { return nil }

        // The backdrop is drawn at FULL opacity whatever the reveal: it is
        // the readability plate, not the words, and a plate that faded or
        // wiped with them would flicker under every caption. The outline
        // needs no decision at all — it is a glyph attribute, so it arrives
        // and leaves with its own glyph. `drawText`'s own condition for
        // drawing words decides which goes down first.
        let wordsFirst = reveal.word != nil && props.wordStyle != nil
        if let backdrop = props.backdrop, !wordsFirst {
            drawBackdrop(backdrop, size: layout.size, under: false, in: context)
        }
        LayerRenderers.drawText(layout, of: props, reveal: reveal, in: context)
        if let backdrop = props.backdrop, wordsFirst {
            drawBackdrop(backdrop, size: layout.size, under: true, in: context)
        }
        return context
    }

    // MARK: - Drawing a reveal

    /// Draws the text of `layout` as much of it as `reveal` says is showing.
    ///
    /// No animation, or a reveal that has finished, takes the ORIGINAL path —
    /// one `CTFrameDraw` — which is what makes a full reveal BYTE-identical
    /// to a clip with no animation at all. The span machinery is not asked to
    /// reproduce `CTFrameDraw` exactly at 1.0; it is not called at all.
    private static func drawText(
        _ layout: TextLayout, of props: TextProps, reveal: RecipeReveal, in context: CGContext
    ) {
        // A timed page draws its words and nothing else (W-5: a styled page
        // gets a WHOLE reveal). A page whose `word` is null — untimed, or a
        // count mismatch — falls through and draws static. The dim is
        // handed on only when the rule says the bitmap draws it (W-16).
        if let word = reveal.word, let style = props.wordStyle {
            drawWords(
                layout, of: props, style: style, word: word, pop: reveal.wordPop,
                glide: reveal.wordGlide, fill: reveal.wordFill,
                dim: wordDim(of: props, reveal: reveal).onLayer ? nil : reveal.wordDim,
                in: context)
            return
        }
        guard let frame = layout.frame else { return }
        let amount = min(max(reveal.amount, 0), 1)
        guard let kind = reveal.kind, amount < 1 else {
            CTFrameDraw(frame, context)
            return
        }
        guard amount > 0, !layout.lines.isEmpty else { return }
        // `CTFrameDraw` sets the text matrix up for you; `CTLineDraw` does
        // not, and glyphs would come out under whatever the context last held.
        context.textMatrix = .identity
        switch kind {
        case .typewriter:
            typewriter(layout, content: props.laidContent, amount: amount, in: context)
        case .wordFade:
            wordFade(
                layout, content: props.laidContent, amount: amount, leaving: reveal.isLeaving,
                in: context)
        case .lineRise:
            lineRise(layout, amount: amount, leaving: reveal.isLeaving, in: context)
        }
    }

    static func drawLaidLine(_ laid: TextLine, in context: CGContext) {
        context.textPosition = laid.origin
        CTLineDraw(laid.line, context)
    }

    /// One laid-out line drawn at `alpha`, as a SINGLE composite.
    ///
    /// An outlined glyph is filled and THEN stroked — `attributedString`
    /// sets a negative `.strokeWidth`, which is Core Text's spelling of
    /// "fill and stroke" — and `CGContext.setAlpha` applies to each of those
    /// two draws separately. The inner half of the stroke lands on ink the
    /// fill has already laid down, so at a partial alpha it composites twice
    /// and comes out both denser and the wrong colour: a black outline on a
    /// white word reads as a heavy grey halo for the whole ramp and snaps to
    /// a crisp edge only at reveal 1. Nothing before this phase could see it,
    /// because a text texture was only ever faded whole, in the shader, where
    /// the per-clip opacity meets the FINISHED pixels once.
    ///
    /// A transparency layer is that same "once": both passes draw at alpha 1
    /// into a buffer and the alpha is applied to the result. An opaque line
    /// skips it — at alpha 1 the stroke covers the fill exactly as it would
    /// in the finished glyph, and an intermediate buffer would buy nothing
    /// but a rounding step and a full-canvas allocation.
    static func drawFaded(_ laid: TextLine, alpha: Double, in context: CGContext) {
        context.setAlpha(CGFloat(alpha))
        guard alpha < 1 else {
            drawLaidLine(laid, in: context)
            return
        }
        context.beginTransparencyLayer(auxiliaryInfo: nil)
        drawLaidLine(laid, in: context)
        context.endTransparencyLayer()
    }

    /// Maximal runs of non-whitespace characters, as UTF-16 ranges.
    ///
    /// Not `enumerateSubstrings(options: .byWords)`, which skips punctuation:
    /// a comma would then belong to no token and never be drawn at all. Every
    /// visible glyph belongs to exactly one token here.
    static func tokens(of content: String) -> [Range<Int>] {
        var tokens: [Range<Int>] = []
        var start: Int?
        for index in content.indices {
            let offset = index.utf16Offset(in: content)
            if content[index].isWhitespace {
                if let from = start { tokens.append(from..<offset) }
                start = nil
            } else if start == nil {
                start = offset
            }
        }
        if let from = start { tokens.append(from..<content.utf16.count) }
        return tokens
    }

    /// The x halfway between two string indices on one line: the middle of
    /// the whitespace between two words. `CTLineGetOffsetForStringIndex`
    /// reads the line as it was ALREADY laid out, so it never re-shapes and
    }

    // MARK: - Rasterizing

    /// A shape description drawn into its own box.
    ///
    /// Since format version 6 the area kinds may carry a GRADIENT instead of
    /// a flat fill (§5.2's `shape.gradient`). It takes precedence over `fill`
    /// and does not clear it, so the model keeps the colour underneath and
    /// `{"gradient": null}` is an exact inverse; `line` and `arrow` ignore it
    /// altogether — `drawLine` below is not even told about it — which is
    /// `radius`'s precedent, stored on every kind and read only by the
    /// rectangle arm.
    private func renderShape(_ props: ShapeProps) -> Rendered? {
        let size = CGSize(
            width: min(CGFloat(LayerRenderers.maxTextureSide), max(1, CGFloat(props.width).rounded(.up))),
            height: min(CGFloat(LayerRenderers.maxTextureSide), max(1, CGFloat(props.height).rounded(.up))))
        guard let context = LayerRenderers.bitmap(size) else { return nil }
        let strokeWidth = props.stroke.map { max(0, CGFloat($0.width)) } ?? 0
        // Inset by half the stroke so it lands INSIDE the box: the box is the
        // layer's source size and growing the texture would move the layer.
        let rect = CGRect(origin: .zero, size: size).insetBy(
            dx: strokeWidth / 2, dy: strokeWidth / 2)
        context.setLineWidth(strokeWidth)
        context.setLineCap(.round)
        context.setLineJoin(.round)
        if let stroke = props.stroke { context.setStrokeColor(stroke.color.nsColor.cgColor) }
        if let fill = props.fill { context.setFillColor(fill.nsColor.cgColor) }

        switch props.kind {
        case .rectangle:
            let radius = min(CGFloat(props.radius), min(rect.width, rect.height) / 2)
            let path = CGPath(
                roundedRect: rect, cornerWidth: max(0, radius), cornerHeight: max(0, radius),
                transform: nil)
            draw(path, in: context, props: props, box: rect, strokeWidth: strokeWidth)
        case .ellipse:
            draw(CGPath(ellipseIn: rect, transform: nil), in: context, props: props,
                box: rect, strokeWidth: strokeWidth)
        case .line, .arrow:
            drawLine(props, in: context, size: size, strokeWidth: strokeWidth)
        }
        return upload(context, size: size)
    }

    /// One area shape: the interior, then the outline.
    ///
    /// The interior is the gradient when the description carries one and the
    /// flat `fill` otherwise — the precedence rule, in the one place that
    /// draws. The STROKE is untouched by it and keeps `stroke.color`: a
    /// gradient describes an area, and a gradient stroke would need a second
    /// stop list nobody has asked for.
    private func draw(
        _ path: CGPath, in context: CGContext, props: ShapeProps, box: CGRect,
        strokeWidth: CGFloat
    ) {
        let painted =
            props.gradient.map { LayerRenderers.paint($0, path: path, box: box, in: context) }
            ?? false
        if !painted, props.fill != nil {
            context.addPath(path)
            context.fillPath()
        }
        if props.stroke != nil, strokeWidth > 0 {
            context.addPath(path)
            context.strokePath()
        }
    }

    /// The `CGGradient` a stop list describes, in the bitmap's own sRGB
    /// space, or nil when there is nothing to ramp between.
    ///
    /// **The stops are SORTED here**, which reads as defensive noise until
    /// you know the core deliberately does not police the order.
    /// `CGGradient` leaves an unsorted `locations` array undefined, so the
    /// obvious home for the requirement is a refusal in `props_check.rs` —
    /// and that refusal has a failure mode nobody would accept: dragging one
    /// stop past another is how a gradient is edited, and the drag would stop
    /// working half way through. The core says so where the check would have
    /// gone, and the sort lands here, at the one call that needs it.
    /// `sortedStops` is stable, so two stops at one position keep the order
    /// they were written in and the picture does not flip mid-drag.
    ///
    /// Fewer than two stops is refused by the core and answered nil here, so
    /// a hand-written file that got one past falls back to the flat `fill`
    /// rather than drawing nothing.
    ///
    /// One measured thing to know before reading a pixel off one of these:
    /// `CGGradient` is sampled at pixel CENTRES and interpolated through a
    /// table of its own, so a black-to-white ramp across 64 columns reads 2
    /// at the first and 254 at the last (never 0 and 255), and the columns
    /// between it wobble by up to 3/255 from the straight line — monotonic,
    /// deterministic, identical row to row, but not arithmetic. Two ramps
    /// that ought to be each other's mirror differ by that much for the same
    /// reason.
    private static func cgGradient(for gradient: Gradient) -> CGGradient? {
        let stops = gradient.sortedStops
        guard stops.count >= 2, let space = CGColorSpace(name: CGColorSpace.sRGB)
        else { return nil }
        // `RGBA.nsColor` is built with `srgbRed:`, so these colours are
        // already in the space they are declared in and in the one the bitmap
        // holds — the same conversion `setFillColor` gets on the flat path,
        // which is what keeps a one-colour gradient byte-identical to it.
        let colors = stops.map { $0.color.nsColor.cgColor } as CFArray
        let locations = stops.map { CGFloat(min(max($0.at, 0), 1)) }
        return CGGradient(colorsSpace: space, colors: colors, locations: locations)
    }

    /// Paints `gradient` inside `path`, and answers whether it drew.
    ///
    /// The paint is a CLIP, not a transparency layer: `addPath`, `clip`, then
